package com.franco.desco.adapter.in.web.resourceprogram;import com.franco.desco.application.resourceprogram.*;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.resourceprogram.ResourceProgramModels;import org.springframework.stereotype.Component;
@Component public class ResourceProgramWebMapper{public ResourceProgramCommands.ListResources list(int p,int t,String estado,Long camp,Long op,Long salida){return new ResourceProgramCommands.ListResources(new PageRequest<>(p,t,new ResourceProgramCommands.Filter(estado,camp,op,salida),null,null));}public ResourceProgramResponses.Summary response(ResourceProgramModels.Summary x){return new ResourceProgramResponses.Summary(x.recursoProgramadoId(),x.campaniaVentaId(),x.operativoVentaId(),x.salidaCampoId(),x.bienInventarioId(),x.bien(),x.suministroId(),x.suministro(),x.cantidadProgramada(),x.estadoProceso(),x.fechaProgramacion(),x.observacion(),x.cantidadEjecutada(),x.cantidadDevuelta());}public ResourceProgramResponses.Detail response(ResourceProgramModels.Detail x){return new ResourceProgramResponses.Detail(x.recursoProgramadoId(),x.campaniaVentaId(),x.operativoVentaId(),x.salidaCampoId(),x.bienInventarioId(),x.bien(),x.estadoBien(),x.suministroId(),x.suministro(),x.unidadMedida(),x.cantidadProgramada(),x.observacion(),x.estado(),x.estadoProceso(),x.usuarioProgramacionId(),x.fechaProgramacion(),x.usuarioCancelacionId(),x.fechaCancelacion(),x.motivoCancelacion(),x.movimientos().stream().map(m->new ResourceProgramResponses.Movement(m.recursoMovimientoId(),m.tipoMovimiento(),m.cantidad(),m.fechaHora(),m.observacion(),m.usuario())).toList());}public ResourceProgramResponses.Availability response(ResourceProgramModels.Availability x){return new ResourceProgramResponses.Availability(x.bienes().stream().map(b->new ResourceProgramResponses.AvailableAsset(b.bienInventarioId(),b.codigoPatrimonial(),b.nombre(),b.estadoBien(),b.disponible())).toList(),x.suministros().stream().map(s->new ResourceProgramResponses.AvailableSupply(s.suministroId(),s.codigo(),s.nombre(),s.unidadMedida(),s.stockDisponible())).toList());}}
